            return False
    return True

def solve_math_problem(n: int) -> int:
    """
    Finds how many n-digit primes can be turned into perfect cubes 
    with a permutation of their digits.
    """
    if n < 1:
        return 0

    lower = 10**(n - 1)
    upper = 10**n - 1

    # Find all n-digit perfect cubes
    cubes: Set[str] = set()
    i = 0
    while True:
        cube = i**3
        if cube > upper:
            break
        if cube >= lower:
            cubes.add("".join(sorted(str(cube))))
        i += 1

    # Find all n-digit primes and check if their sorted digits match a cube
